insert into public.takipler (takip_eden_id, takip_edilen_id, durum)
select t.takip_edilen_id, t.takip_eden_id, 'kabul'
from public.takipler t
where t.durum = 'kabul'
on conflict (takip_eden_id, takip_edilen_id) do nothing;
