        <Pressable
          key={s.anahtar}
          style={stiller.sekme}
          onPress={() => onSec(s.anahtar)}
          accessibilityRole="button"
          accessibilityState={{ selected: s.anahtar === secili }}
        >
          <Text style={[stiller.yazi, s.anahtar === secili && stiller.yaziAktif]}>{s.etiket}</Text>
        </Pressable>
      ))}
    </View>
  )
}

