const DILLER = ['tr', 'en', 'de', 'es', 'fr', 'ru', 'ar']
const KOK_DIL = 'tr'
const KULLANICI_ADI = /^[a-z0-9._]{3,20}$/
const SAGDAN_SOLA = ['ar']

