}

function dilSec(istek) {
  const cerez = (istek.headers.get('Cookie') || '').split(';').map((p) => p.trim()).find((p) => p.startsWith('dil='))
  const secim = cerez ? cerez.slice(4) : null
  if (secim && DILLER.includes(secim)) return secim
