    s = yukle(p)
    s = rep(s, "import { profilBaglantisi } from '../../../lib/paylasim'\n",
            "import { profilBaglantisi, sistemPaylasimi } from '../../../lib/paylasim'\n")
    s = rep(s, "      await Share.share({\n", "      await sistemPaylasimi({\n")
    yaz(p, s)

# ---- CheckInKarti: dokunuslari koru ----
p = os.path.join('src', 'tasarim', 'CheckInKarti.tsx')
s = yukle(p)
s = rep(s, "import { FotografAltyazisi } from './FotografAltyazisi'\n",
        "import { FotografAltyazisi } from './FotografAltyazisi'\nimport { paylasimSonrasiBaskiMi } from '../../lib/paylasim'\n")
s = rep(s, "  const [buyukAcik, setBuyukAcik] = useState(false)\n",
        """  const [buyukAcik, setBuyukAcik] = useState(false)

  // iOS paylasim sayfasi disina dokunarak kapatilinca dokunus karta da
  // dusuyor (2026-09-18); kapanistan hemen sonraki basislar yutuluyor.
  const korumali = (fn: () => void) => () => {
    if (paylasimSonrasiBaskiMi()) return
    fn()
  }
""")
s = rep(s, "            onPress={() => setMenuAcik(true)}", "            onPress={korumali(() => setMenuAcik(true))}")
s = rep(s, "            onPress={() => onBegen?.(oge.id)}", "            onPress={korumali(() => onBegen?.(oge.id))}")
s = rep(s, """            onPress={() => {
              setYorumlarAcik(true)
              onYorum?.(oge.id)
            }}""", """            onPress={korumali(() => {
              setYorumlarAcik(true)
              onYorum?.(oge.id)
            })}""")
s = rep(s, "            onPress={() => onPaylas?.(oge.id)}", "            onPress={korumali(() => onPaylas?.(oge.id))}")
s = rep(s, "          onPress={() => (onFotografAc ? onFotografAc() : setBuyukAcik(true))}",
        "          onPress={korumali(() => (onFotografAc ? onFotografAc() : setBuyukAcik(true)))}")
yaz(p, s)
print('ok')

