export async function sistemPaylasimi(icerik: ShareContent): Promise<void> {
  try {
    await Share.share(icerik)
  } finally {
    sonKapanis = Date.now()
  }
}

export function paylasimSonrasiBaskiMi(simdi: number = Date.now()): boolean {
