// Apple App ID'ye Associated Domains yetenegini ekler - EAS'in kendi
// apple-utils kutuphanesi ve onbellekteki portal oturumuyla (~/.app-store).
const D = 'C:/Users/orcns/AppData/Local/npm-cache/_npx/6bc7bae5c2059953/node_modules'
const au = require(D + '/@expo/apple-utils')
const { syncCapabilitiesForEntitlementsAsync } = require(D + '/eas-cli/build/credentials/ios/appstore/bundleIdCapabilities.js')

async function main() {
  const ozet = (s) => (s ? String(s).replace(/[A-Za-z0-9+/=_-]{24,}/g, '[gizli]') : s)
  au.Auth.resetInMemoryData()
  const restored = await au.Auth.tryRestoringAuthStateFromUserCredentialsAsync(
    { username: 'byorcun@hotmail.com', teamId: '[SIR-GIZLENDI]' },
    { autoResolveProvider: true }
  )
  if (!restored) {
    console.log('OTURUM GERI YUKLENEMEDI - portal girisi gerekiyor')
    process.exit(2)
  }
  const ctx = restored.context
  console.log('oturum ok, team', ctx.teamId)
  const bundleId = await au.BundleId.findAsync(ctx, { identifier: 'com.slooin.app' })
  if (!bundleId) throw new Error('bundle id bulunamadi')
  const before = await bundleId.getBundleIdCapabilitiesAsync()
  console.log('once:', before.map((c) => c.attributes.capabilityType ?? c.id).join(', '))
  await syncCapabilitiesForEntitlementsAsync(bundleId, {
    'com.apple.developer.associated-domains': ['applinks:slooin.com'],
    'com.apple.developer.applesignin': ['Default'],
    'aps-environment': 'production',
  })
  const after = await bundleId.getBundleIdCapabilitiesAsync()
  console.log('sonra:', after.map((c) => c.attributes.capabilityType ?? c.id).join(', '))
}
main().catch((e) => {
  console.error('HATA:', e.message)
  process.exit(1)
})

