assert s.count(old)==1; s=s.replace(old,new)
s=s.replace(""" * Kalkan, paylasim
 * sayfasi kapandiktan sonraki kisa pencerede butun dokunuslari yutar;""",""" * Kalkan, paylasim
 * sayfasi ACILDIGI ANDAN kapanistan 700 ms sonrasina kadar butun
 * dokunuslari yutar (ilk surum yalnizca kapanistan sonra aciyordu ve
 * YETMEDI - kapatma dokunusu sayfa kapanmadan dusuyor);""")
open(p,'w',encoding='utf-8',newline='').write(s)

# test: acilista kalkan var
p=os.path.join('__tests__','ekranlar','_layout.test.tsx'); s=open(p,encoding='utf-8').read()
