    // Sayfa ACIKKEN kalkan var (kapatma dokunusu sayfa kapanmadan dusuyor).
    let cozul: () => void = () => {}
    paylasSpy.mockReturnValue(new Promise<{ action: string }>((r) => { cozul = () => r({ action: 'dismissedAction' }) }) as never)
    let bitti: Promise<void> = Promise.resolve()
