import { useEffect, useState } from 'react'
import { BrowserRouter, Link, Navigate, Route, Routes } from 'react-router-dom'
import { supabase } from './supabase'
import { Giris } from './ekranlar/Giris'
import { Sikayetler } from './ekranlar/Sikayetler'
import { SikayetDetayi } from './ekranlar/SikayetDetayi'
import { Kullanicilar } from './ekranlar/Kullanicilar'
import { KullaniciDetayi } from './ekranlar/KullaniciDetayi'
import { Konusma } from './ekranlar/Konusma'
import { DenetimIzi } from './ekranlar/DenetimIzi'
import { DuzenlemeTalepleri } from './ekranlar/DuzenlemeTalepleri'
import { Yukleniyor } from './ortak/Durum'

export default function App() {
  // null = henuz sorulmadi. Yetki sorusunu SUNUCU cevaplar
  // (moderator_muyum); panel kendi kararini vermez.
  const [yetkili, setYetkili] = useState<boolean | null>(null)

  useEffect(() => {
    let iptal = false

    async function kontrolEt() {
      const { data } = await supabase.rpc('moderator_muyum')
      if (!iptal) setYetkili(data === true)
    }

    const { data: abone } = supabase.auth.onAuthStateChange(() => {
      kontrolEt()
    })
    kontrolEt()

    return () => {
      iptal = true
      abone.subscription.unsubscribe()
    }
  }, [])

  if (yetkili === null) return <Yukleniyor ne="Oturum" />

  if (!yetkili) {
    return <Giris onGirildi={() => setYetkili(true)} />
  }

  return (
    <BrowserRouter>
      <header>
        <strong>Slooin moderasyon</strong>
        <nav>
          <Link to="/sikayetler">Şikayetler</Link>
          <Link to="/kullanicilar">Kullanıcılar</Link>
          <Link to="/talepler">Düzenleme talepleri</Link>
          <Link to="/iz">Denetim izi</Link>
        </nav>
        <button
          onClick={async () => {
            await supabase.auth.signOut()
            setYetkili(false)
          }}
        >
          Çıkış yap
        </button>
      </header>

      <main>
        <Routes>
          <Route path="/" element={<Navigate to="/sikayetler" replace />} />
          <Route path="/sikayetler" element={<Sikayetler />} />
          <Route path="/sikayetler/:id" element={<SikayetDetayi />} />
          <Route path="/kullanicilar" element={<Kullanicilar />} />
          <Route path="/kullanicilar/:id" element={<KullaniciDetayi />} />
          <Route path="/konusma/:id" element={<Konusma />} />
          <Route path="/talepler" element={<DuzenlemeTalepleri />} />
          <Route path="/iz" element={<DenetimIzi />} />
        </Routes>
      </main>
    </BrowserRouter>
  )
}
/* Panel bir vitrin degil. Olcut okunabilirlik ve yanlis tiklamayi
   zorlastirmak; tablo agirlikli, veri yogun, sade. */

:root {
  --metin: #1a1a1a;
  --soluk: #666;
  --cizgi: #e3e3e3;
  --zemin: #fff;
  --vurgu: #FF6B1A;
  --uyari: #b34700;
  --yikici: #c0261a;
  --gizli: #f5f5f5;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  color: var(--metin);
  background: var(--zemin);
  font-size: 15px;
  line-height: 1.5;
}

header {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 12px 24px;
  border-bottom: 1px solid var(--cizgi);
}

header nav { display: flex; gap: 16px; flex: 1; }
header a { color: var(--metin); text-decoration: none; }
header a:hover { color: var(--vurgu); }

main { padding: 24px; max-width: 1100px; }

h2 { margin-top: 0; }
h3 { margin-top: 28px; }

table { border-collapse: collapse; width: 100%; margin-top: 12px; }
th, td { text-align: left; padding: 8px 10px; border-bottom: 1px solid var(--cizgi); vertical-align: top; }
th { font-weight: 600; color: var(--soluk); font-size: 13px; }
tr.gizlenmis { background: var(--gizli); color: var(--soluk); }
tr.okuma td { background: #fff8f3; }

.filtreler { display: flex; gap: 8px; margin: 12px 0; }
.arama { display: flex; gap: 8px; margin: 12px 0; }
.arama input { flex: 1; }

input, select, textarea {
  padding: 8px;
  border: 1px solid var(--cizgi);
  border-radius: 4px;
  font: inherit;
  background: #fff;
}
textarea { width: 100%; resize: vertical; }

button, .dugme {
  padding: 8px 14px;
  border: 1px solid var(--cizgi);
  border-radius: 4px;
  background: #fff;
  font: inherit;
  cursor: pointer;
  text-decoration: none;
  color: var(--metin);
  display: inline-block;
}
button:hover { border-color: var(--soluk); }
button:disabled { opacity: 0.5; cursor: default; }

.birincil { background: var(--vurgu); border-color: var(--vurgu); color: #fff; }
.birincil:hover { border-color: var(--uyari); }
.yikici { color: var(--yikici); border-color: var(--yikici); }

.durum { color: var(--soluk); }
