// 'yorum' 2026-09-02'de eklendi (begeni/yorum ozelligiyle birlikte).
export type HedefTuru = 'kullanici' | 'check_in' | 'mesaj' | 'yorum'

export type SikayetSatiri = {
  id: string
  hedef_tur: HedefTuru
  hedef_id: string
  sebep: string
  aciklama: string | null
  durum: SikayetDurumu
  olusturuldu: string
  sikayet_eden_adi: string | null
  hedef_adi: string | null
  hedefin_sikayeti: number
}

export type Profil = {
  id: string
  ad: string
  kullanici_adi: string
  biyografi: string | null
  fotograflar: string[]
  dogum_tarihi: string
  aramada_gorunsun: boolean
}

export type HesapDurumu = {
  kullanici_id: string
  durum: 'askida' | 'yasakli' | 'dondurulmus'
  aski_bitisi: string | null
  gerekce: string
  moderator_id: string | null
  guncellendi: string
}

export type CheckInOzeti = {
  id: string
  mekan_adi: string
  not_metni: string | null
  fotograf: string | null
  olusturma_zamani: string
  canli_mi: boolean
  gorunurluk: string
  bulunurluk: string
  moderasyon_gizli: boolean
}

/**
 * Sikayet edilen yorum ve YAZILDIGI PAYLASIM.
 *
 * Baglam olmadan "bu yorum taciz mi" sorusu cevaplanamaz; bu yuzden
 * sunucu yorumun metniyle birlikte paylasimin notunu ve mekani da
 * donduruyor.
 */
export type YorumOzeti = {
  id: string
  check_in_id: string
  kullanici_id: string | null
  metin: string
  olusturuldu: string
  /** Sikayet uzerine ANINDA konan gecici gizlilik. */
  sikayet_gizli: boolean
  /** Moderatorun kalici karari. */
  moderasyon_gizli: boolean
  paylasim_sahibi: string | null
  paylasim_notu: string | null
  mekan_adi: string
}

export type Mesaj = {
  id: string
  konusma_id: string
  gonderen_id: string | null
  metin: string
  olusturuldu: string
}

export type SikayetDetayi = {
  sikayet: {
    id: string
    sikayet_eden_id: string | null
    hedef_tur: HedefTuru
    hedef_id: string
    sebep: string
    aciklama: string | null
    durum: SikayetDurumu
    olusturuldu: string
    karar_veren_id: string | null
    karar_zamani: string | null
    moderator_notu: string | null
  }
  sikayet_eden: Profil | null
  hedef: Profil | CheckInOzeti | Mesaj | YorumOzeti | null
}

export type KullaniciOzeti = {
  id: string
  ad: string
  kullanici_adi: string
  durum: string | null
  sikayet_sayisi: number
}

export type KonusmaOzeti = {
  konusma_id: string
  karsi_taraf: string | null
  mesaj_sayisi: number
  ilk_mesaj: string | null
  son_mesaj: string | null
}

export type KullaniciDetayi = {
  profil: Profil | null
  hesap_durumu: HesapDurumu | null
  check_inler: CheckInOzeti[]
  takipler: { karsi_taraf: string; durum: string; olusturuldu: string }[]
  engelledikleri: string[]
  onu_engelleyenler: string[]
  sohbet_istekleri: {
    gonderen_id: string
    alan_id: string
    durum: string
    olusturuldu: string
  }[]
  bugunku_istek_sayisi: number
  konusmalar: KonusmaOzeti[]
  bildirim_cihazi: number
  sikayet_ozeti: { hakkinda: number; actigi: number }
}

// Kademe 1 = sikayet baglami (varsayilan), kademe 2 = tum konusma.
// Ayrim yalnizca gorsel degil: denetim izine de ayri turde duser.
export type KonusmaIcerigi = {
  kademe: 1 | 2
  uyeler: string[]
  mesajlar: Mesaj[]
}

export type IzSatiri = {
  id: string
  moderator_id: string | null
  eylem: string
  hedef_tur: string
  hedef_id: string
  ayrinti: Record<string, unknown> | null
  olusturuldu: string
}
import type { ReactNode } from 'react'

export function Yukleniyor({ ne = 'Veriler' }: { ne?: string }) {
  return <p className="durum">{ne} yükleniyor…</p>
}

export function Hata({ mesaj }: { mesaj: string | null }) {
  if (!mesaj) return null
  return <p className="durum hata">{mesaj}</p>
}

export function BosDurum({ children }: { children: ReactNode }) {
  return <p className="durum bos">{children}</p>
}

/** Hata mesajini kullaniciya gosterilebilir bir metne cevirir. */
export function hataMetni(e: unknown): string {
  if (e && typeof e === 'object' && 'message' in e) {
    return String((e as { message: unknown }).message)
  }
  return 'Bir sorun oluştu'
}

/** Sunucudan gelen zaman damgasini okunur hale getirir. */
export function zaman(deger: string | null): string {
  if (!deger) return '—'
  return new Date(deger).toLocaleString('tr-TR')
}
import { useState } from 'react'

type Props = {
  baslik: string
  aciklama?: string
  eylemEtiketi: string
  /** Yikici eylemlerde ayri bir onay adimi cikar. */
  onayGerekli?: boolean
  onayMetni?: string
  onIptal: () => void
  onSonuc: (gerekce: string) => Promise<void> | void
}

/**
 * Gerekce isteyen kalip. Sunucu zaten en az 3 karakter gerekce zorluyor
 * (moderasyon RPC'leri); burasi o kuralin arayuz karsiligi ve
 * moderatorun ne yaptigini bilerek yapmasini sagliyor.
 *
 * Yikici eylemlerde (askiya alma, yasaklama, gizleme, tum konusmayi
 * acma) `onayGerekli` ile ikinci bir adim eklenir: gerekce yazmak tek
 * basina yeterli degil, ayrica onaylamak gerekir.
 */
export function GerekceSor({
  baslik,
  aciklama,
  eylemEtiketi,
  onayGerekli = false,
  onayMetni,
  onIptal,
  onSonuc,
}: Props) {
  const [gerekce, setGerekce] = useState('')
  const [onaylandi, setOnaylandi] = useState(false)
  const [calisiyor, setCalisiyor] = useState(false)

  const gerekceYeterli = gerekce.trim().length >= 3
  const gonderilebilir = gerekceYeterli && (!onayGerekli || onaylandi) && !calisiyor

  async function gonder() {
    if (!gonderilebilir) return
    setCalisiyor(true)
    try {
      await onSonuc(gerekce.trim())
    } finally {
      setCalisiyor(false)
    }
  }

  return (
    <div className="kaplama">
      <div className="kutu">
        <h3>{baslik}</h3>
        {aciklama && <p className="kutu-aciklama">{aciklama}</p>}

        <label htmlFor="gerekce">Gerekçe (denetim izine yazılır)</label>
        <textarea
          id="gerekce"
          value={gerekce}
          onChange={(e) => setGerekce(e.target.value)}
          rows={3}
          placeholder="Bu erişimin ya da işlemin sebebi"
        />
        {!gerekceYeterli && gerekce.length > 0 && (
          <p className="ipucu">En az 3 karakter yaz.</p>
        )}

        {onayGerekli && (
          <label className="onay">
            <input
              type="checkbox"
              checked={onaylandi}
              onChange={(e) => setOnaylandi(e.target.checked)}
            />
            {onayMetni ?? 'Bu işlemi yapmak istediğimi onaylıyorum.'}
          </label>
        )}

        <div className="kutu-dugmeler">
          <button type="button" onClick={onIptal} disabled={calisiyor}>
            Vazgeç
          </button>
          <button
            type="button"
            className="birincil"
            onClick={gonder}
            disabled={!gonderilebilir}
          >
            {calisiyor ? 'Çalışıyor…' : eylemEtiketi}
          </button>
        </div>
      </div>
    </div>
  )
}
import { createClient } from '@supabase/supabase-js'

const url = import.meta.env.VITE_SUPABASE_URL
const anon = import.meta.env.VITE_SUPABASE_ANON_KEY

if (!url || !anon) {
  throw new Error(
    'VITE_SUPABASE_URL ve VITE_SUPABASE_ANON_KEY tanimli olmali (panel/.env)'
  )
}

// Panelde service-role anahtari YOKTUR (spec karar 55). Butun erisim
// moderator hesabinin oturumu uzerinden, security definer RPC'lerle
// olur ve yetki kapisi veritabanindadir: moderatorler tablosunda satir
// + JWT'nin aal talebi 'aal2'. Bu yuzden panelin paketinde hicbir sir
// yok ve barinma sorusu bir guvenlik sorusu degil.
export const supabase = createClient(url, anon)
import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import App from './App'
import './stil.css'

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <App />
  </StrictMode>
)
