  if (yukleniyor) return <Yukleniyor ne="Talepler" />

  return (
    <section>
      <h2>Düzenleme talepleri</h2>

      <div className="filtreler">
        <select value={durum} onChange={(e) => setDurum(e.target.value)}>
          <option value="beklemede">Bekleyen</option>
          <option value="onaylandi">Onaylanan</option>
          <option value="reddedildi">Reddedilen</option>
          <option value="">Hepsi</option>
        </select>
      </div>

      {hata && <Hata mesaj={hata} />}

      {satirlar.length === 0 ? (
        <BosDurum>Bu durumda talep yok.</BosDurum>
      ) : (
        <table>
          <thead>
            <tr>
              <th>Mekân</th>
              <th>Önerilen</th>
              <th>Tarih</th>
              <th />
            </tr>
          </thead>
          <tbody>
            {satirlar.map((s) => (
              <tr key={s.id}>
                <td>
                  {s.mekan_adi}
                  <br />
                  <small>{s.mekan_turu}</small>
                </td>
                <td>
                  {[
                    s.onerilen_ad && `Ad: ${s.onerilen_ad}`,
                    s.onerilen_mahalle && `Mahalle: ${s.onerilen_mahalle}`,
                    s.onerilen_adres && `Adres: ${s.onerilen_adres}`,
                    s.onerilen_il && `İl: ${s.onerilen_il}`,
                    s.onerilen_ilce && `İlçe: ${s.onerilen_ilce}`,
                    s.onerilen_tur && `Tür: ${s.onerilen_tur}`,
                    s.kapali_bildirimi && 'KAPANDI bildirimi',
                    s.fotograf && 'Kapak fotoğrafı',
                  ]
                    .filter(Boolean)
                    .join(' · ')}
                </td>
                <td>{zaman(s.olusturuldu)}</td>
                <td>
                  <button onClick={() => detayAc(s.id)}>İncele</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      {acik && (
        <div className="detay">
          <h3>{acik.mevcut_ad}</h3>
          <p>
            <small>
              {[acik.mevcut_semt, acik.mevcut_il].filter(Boolean).join(', ')} ·{' '}
              {acik.gonderen_adi ?? 'silinmiş kullanıcı'} · {zaman(acik.olusturuldu)}
            </small>
          </p>

          {/* MEVCUT ve ONERILEN YAN YANA: moderator karsilastirma
              yapmadan karar veremez. */}
          <table>
            <tbody>
              <tr>
                <th>Ad</th>
                <td>{acik.mevcut_ad}</td>
                <td>{acik.onerilen_ad ?? '—'}</td>
              </tr>
              <tr>
                <th>Mahalle</th>
                <td>{acik.mevcut_mahalle ?? '—'}</td>
                <td>{acik.onerilen_mahalle ?? '—'}</td>
              </tr>
              <tr>
                <th>Adres</th>
                <td>{acik.mevcut_adres ?? '—'}</td>
                <td>{acik.onerilen_adres ?? '—'}</td>
              </tr>
              <tr>
                <th>İl</th>
                <td>{acik.mevcut_il ?? '—'}</td>
                <td>{acik.onerilen_il ?? '—'}</td>
              </tr>
              <tr>
                <th>İlçe</th>
                <td>{acik.mevcut_semt ?? '—'}</td>
                <td>{acik.onerilen_ilce ?? '—'}</td>
              </tr>
              <tr>
                <th>Tür</th>
                <td>{acik.mevcut_tur}</td>
                <td>{acik.onerilen_tur ?? '—'}</td>
              </tr>
              <tr>
                <th>Durum</th>
                <td>{acik.mevcut_kapali ? 'Kapalı' : 'Açık'}</td>
                <td>{acik.kapali_bildirimi ? 'Kapandı bildirimi' : '—'}</td>
              </tr>
            </tbody>
          </table>

          {fotoUrl && <img src={fotoUrl} alt="Önerilen kapak fotoğrafı" width={320} />}

          <fieldset>
            <legend>Onaylanacak alanlar</legend>
            {ALANLAR.filter((a) => a.anahtar !== 'kapali' || acik.kapali_bildirimi).map((a) => (
              <label key={a.anahtar}>
                <input
                  type="checkbox"
                  checked={secili.includes(a.anahtar)}
                  onChange={(e) =>
                    setSecili((m) =>
                      e.target.checked ? [...m, a.anahtar] : m.filter((x) => x !== a.anahtar)
                    )
                  }
                />
                {a.etiket}
              </label>
            ))}
          </fieldset>

          <textarea
            value={not}
            onChange={(e) => setNot(e.target.value)}
            placeholder="Karar notu (isteğe bağlı)"
          />

          <div className="eylemler">
            <button onClick={() => kararVer('onaylandi')} disabled={isliyor}>
              Onayla
            </button>
            <button onClick={() => kararVer('reddedildi')} disabled={isliyor}>
              Reddet
            </button>
            {/* KAPATMA GERI ALINABILIR. Yanlis bir bildirim mekani
                butun listelerden duesueruyor; geri alinamayan bir
                moderasyon eylemi birakmak tek bir hatali onayi kalici
                yapardi (ayni gerekce yorum gizlemede de var). */}
            {acik.mevcut_kapali && (
              <button onClick={geriAc} disabled={isliyor}>
                Mekânı geri aç
              </button>
            )}
            <button onClick={() => setAcik(null)}>Kapat</button>
          </div>
        </div>
      )}
    </section>
  )
}
import { useCallback, useEffect, useState } from 'react'
import { supabase } from '../supabase'
import { BosDurum, Hata, Yukleniyor, hataMetni, zaman } from '../ortak/Durum'
import type { IzSatiri } from '../tipler'

// Mesaj okumalari listede AYIRT EDILEBILIR olmali: karar 75'in tek somut
// ciktisi izdeki bu ayrim. Gorunmezse karar kagit uzerinde kalir.
const OKUMA_EYLEMLERI = new Set(['mesaj_baglami', 'konusma_tam'])

const ETIKETLER: Record<string, string> = {
  mesaj_baglami: 'şikayet bağlamı okundu',
  konusma_tam: 'TÜM KONUŞMA okundu',
  kullanici_detayi_goruntulendi: 'kullanıcı detayı görüntülendi',
  sikayet_karara_baglandi: 'şikayet karara bağlandı',
  hesap_askiya_alindi: 'hesap askıya alındı',
  hesap_yasaklandi: 'hesap yasaklandı',
  hesap_durumu_kaldirildi: 'hesap kısıtı kaldırıldı',
  icerik_gizlendi: 'içerik gizlendi',
  gizleme_kaldirildi: 'gizleme kaldırıldı',
}

export function DenetimIzi() {
  const [satirlar, setSatirlar] = useState<IzSatiri[]>([])
  const [hedefTur, setHedefTur] = useState('')
  const [yukleniyor, setYukleniyor] = useState(true)
  const [hata, setHata] = useState<string | null>(null)

  const yukle = useCallback(async () => {
    setYukleniyor(true)
    setHata(null)
    try {
      const { data, error } = await supabase.rpc('moderasyon_kayitlarini_listele', {
        p_hedef_tur: hedefTur || null,
        p_limit: 200,
      })
      if (error) throw error
      setSatirlar((data ?? []) as IzSatiri[])
    } catch (e) {
      setHata(hataMetni(e))
    } finally {
      setYukleniyor(false)
    }
  }, [hedefTur])

  useEffect(() => {
    yukle()
  }, [yukle])

  return (
    <section>
      <h2>Denetim izi</h2>
      <p className="not">
        Bu kayıtlar silinemez ve değiştirilemez; moderatör dahil hiç kimse
        kaldıramaz.
      </p>

      <div className="filtreler">
        <select value={hedefTur} onChange={(e) => setHedefTur(e.target.value)}>
          <option value="">Tüm hedefler</option>
          <option value="kullanici">Kullanıcı</option>
          <option value="check_in">Check-in</option>
          <option value="yorum">Yorum</option>
          <option value="sikayet">Şikayet</option>
          <option value="konusma">Konuşma</option>
        </select>
      </div>

      <Hata mesaj={hata} />

      {yukleniyor ? (
        <Yukleniyor ne="Kayıtlar" />
      ) : satirlar.length === 0 ? (
        <BosDurum>Henüz kayıt yok.</BosDurum>
      ) : (
        <table>
          <thead>
            <tr><th>Zaman</th><th>Eylem</th><th>Hedef</th><th>Gerekçe</th></tr>
          </thead>
          <tbody>
            {satirlar.map((k) => (
              <tr key={k.id} className={OKUMA_EYLEMLERI.has(k.eylem) ? 'okuma' : ''}>
                <td>{zaman(k.olusturuldu)}</td>
                <td>
                  <span className={k.eylem === 'konusma_tam' ? 'etiket genis' : 'etiket'}>
                    {ETIKETLER[k.eylem] ?? k.eylem}
                  </span>
                </td>
                <td>
                  {k.hedef_tur} · {k.hedef_id.slice(0, 8)}
                </td>
                <td>
                  {(k.ayrinti?.gerekce as string | undefined) ?? '—'}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </section>
  )
}

