import { useState } from 'react'
import { supabase } from '../supabase'
import { Hata, hataMetni } from '../ortak/Durum'

type Adim = 'parola' | 'kod'

/**
 * Panel girisi iki asamalidir: parola, ardindan TOTP kodu. Ikinci
 * faktor olmadan alinan oturum `aal1` seviyesindedir ve hicbir
 * moderator RPC'sini cagiramaz - bu kural veritabaninda zorlanir
 * (moderasyon.yetkili_mi), yani bu ekrani atlamak bir sey degistirmez.
 *
 * Ilk kurulumda TOTP kaydi da burada yapilir: enroll bir QR uretir,
 * moderator onu dogrulayici uygulamasina ekler ve ilk kodu girer.
 *
 * KIMLIK E-POSTADIR, telefon degil. Spec karar 56 "kendi telefon
 * numarasi" diyordu ama Supabase'in TOTP'si QR uretirken hesap adi
 * olarak e-postayi kullaniyor; telefon-only hesapta enroll
 * "AccountName must be set" ile 500 doner (auth loglarinda dogrulandi).
 * E-posta ayrica daha uygun: moderator hesabi zaten uygulamadan ayri
 * ve telefon dogrulamasi bos yere SMS maliyeti getiriyordu.
 */
export function Giris({ onGirildi }: { onGirildi: () => void }) {
  const [adim, setAdim] = useState<Adim>('parola')
  const [eposta, setEposta] = useState('')
  const [parola, setParola] = useState('')
  const [kod, setKod] = useState('')
  const [faktorId, setFaktorId] = useState<string | null>(null)
  const [qr, setQr] = useState<string | null>(null)
  const [hata, setHata] = useState<string | null>(null)
  const [calisiyor, setCalisiyor] = useState(false)

  async function girisYap() {
    setHata(null)
    setCalisiyor(true)
    try {
      const { error } = await supabase.auth.signInWithPassword({
        email: eposta.trim(),
        password: parola,
      })
      if (error) {
        setHata(error.message)
        return
      }
      await mfaDurumunuOku()
    } catch (e) {
      setHata(hataMetni(e))
    } finally {
      setCalisiyor(false)
    }
  }

  async function mfaDurumunuOku() {
    const { data, error } = await supabase.auth.mfa.listFactors()
    if (error) {
      setHata(error.message)
      return
    }

    const dogrulanmis = data?.totp?.find((f) => f.status === 'verified')
    if (dogrulanmis) {
      setFaktorId(dogrulanmis.id)
      setAdim('kod')
      return
    }

    // Ilk kurulum: yeni bir TOTP faktoru olustur ve QR goster.
    const { data: kayit, error: kayitHatasi } = await supabase.auth.mfa.enroll({
      factorType: 'totp',
    })
    if (kayitHatasi) {
      setHata(kayitHatasi.message)
      return
    }
    setFaktorId(kayit.id)
    setQr(kayit.totp.qr_code)
    setAdim('kod')
  }

  async function koduDogrula() {
    if (!faktorId) return
    setHata(null)
    setCalisiyor(true)
    try {
      const { data: meydan, error: meydanHatasi } =
        await supabase.auth.mfa.challenge({ factorId: faktorId })
      if (meydanHatasi) {
        setHata(meydanHatasi.message)
        return
      }

      const { error } = await supabase.auth.mfa.verify({
        factorId: faktorId,
        challengeId: meydan.id,
        code: kod.trim(),
      })
      if (error) {
        setHata(error.message)
        return
      }

      // Oturum artik aal2. Moderator olup olmadigini SUNUCU soyler;
      // panelin kendi karari degil.
      const { data: yetkili } = await supabase.rpc('moderator_muyum')
      if (yetkili !== true) {
        // Sebebi gizlemek bir guvenlik kazanci saglamaz, yalnizca hata
        // ayiklamayi zorlastirir.
        setHata('Bu hesap moderatör değil.')
        await supabase.auth.signOut()
        setAdim('parola')
        return
      }

      onGirildi()
    } catch (e) {
      setHata(hataMetni(e))
    } finally {
      setCalisiyor(false)
    }
  }

  return (
    <div className="giris">
      <h1>Slooin moderasyon</h1>

      {adim === 'parola' && (
        <form
          onSubmit={(e) => {
            e.preventDefault()
            girisYap()
          }}
        >
          <label htmlFor="eposta">E-posta</label>
          <input
            id="eposta"
            type="email"
            value={eposta}
            onChange={(e) => setEposta(e.target.value)}
            placeholder="moderator@slooin.app"
            autoComplete="username"
          />

          <label htmlFor="parola">Parola</label>
          <input
            id="parola"
            type="password"
            value={parola}
            onChange={(e) => setParola(e.target.value)}
            autoComplete="current-password"
          />

          <button type="submit" className="birincil" disabled={calisiyor}>
            {calisiyor ? 'Giriş yapılıyor…' : 'Devam et'}
          </button>
        </form>
      )}

      {adim === 'kod' && (
        <form
          onSubmit={(e) => {
            e.preventDefault()
            koduDogrula()
          }}
        >
          {qr && (
            <div className="qr">
              <p>
                Bu, bu hesap için ilk kurulum. Aşağıdaki kodu doğrulayıcı
                uygulamana ekle, sonra ürettiği altı haneli kodu gir.
              </p>
              <img src={qr} alt="TOTP kurulum kodu" />
            </div>
          )}

          <label htmlFor="kod">Doğrulama kodu</label>
          <input
            id="kod"
            value={kod}
            onChange={(e) => setKod(e.target.value)}
            inputMode="numeric"
            placeholder="123456"
            autoComplete="one-time-code"
          />

          <button type="submit" className="birincil" disabled={calisiyor}>
            {calisiyor ? 'Doğrulanıyor…' : 'Giriş yap'}
          </button>
        </form>
      )}

      <Hata mesaj={hata} />
    </div>
  )
}
.durum { color: var(--soluk); }
.durum.hata { color: var(--yikici); }
.durum.bilgi { color: #1a7a3c; }
.not { color: var(--soluk); font-size: 13px; }
.ipucu { color: var(--yikici); font-size: 13px; margin: 4px 0 0; }

.etiket {
  font-size: 12px;
  color: var(--soluk);
  border: 1px solid var(--cizgi);
  border-radius: 3px;
  padding: 1px 5px;
  margin-left: 6px;
}
.etiket.genis { color: #fff; background: var(--yikici); border-color: var(--yikici); }

.rozet { display: inline-block; min-width: 22px; text-align: center; }
.rozet.uyari { color: #fff; background: var(--uyari); border-radius: 10px; padding: 0 6px; }

.durum-rozet { font-size: 12px; padding: 2px 6px; border-radius: 3px; background: #f0f0f0; }
.durum-askida { background: #ffe9d6; color: var(--uyari); }
.durum-yasakli { background: #ffdedb; color: var(--yikici); }
.durum-dondurulmus { background: #e8e8f5; color: #444; }

.ozet { display: grid; grid-template-columns: 180px 1fr; gap: 4px 16px; }
.ozet dt { color: var(--soluk); }
.ozet dd { margin: 0; }

/* Hassas erisimin her zaman gorunur olmasi bilincli: moderator neye
   baktigini ve bunun kaydedildigini unutmamali. */
.uyari-serit {
  background: #fff4ea;
  border-left: 3px solid var(--vurgu);
  padding: 8px 12px;
  font-size: 14px;
}
.uyari-serit.genis {
  background: #ffe9e6;
  border-left-color: var(--yikici);
  font-weight: 600;
}

.kapi { border: 1px dashed var(--cizgi); padding: 24px; text-align: center; }

.mesajlar { list-style: none; padding: 0; }
.mesaj { border: 1px solid var(--cizgi); border-radius: 6px; padding: 8px 12px; margin: 6px 0; }
.mesaj.vurgulu { border-color: var(--vurgu); background: #fff8f3; }
.mesaj-ust { display: block; font-size: 12px; color: var(--soluk); }
.mesaj-metin { display: block; }
blockquote.mesaj { margin: 8px 0; }

.karar-formu { display: grid; gap: 8px; max-width: 520px; }
.aksiyonlar { display: flex; gap: 8px; align-items: center; margin-top: 8px; flex-wrap: wrap; }
.gecmis { padding-left: 18px; }
.sayfalama { display: flex; gap: 12px; align-items: center; margin-top: 16px; }

.giris { max-width: 360px; margin: 80px auto; }
.giris form { display: grid; gap: 6px; }
.giris label { font-size: 13px; color: var(--soluk); margin-top: 8px; }
.giris button { margin-top: 16px; }
.qr { text-align: center; }
.qr img { max-width: 220px; }

.kaplama {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.35);
  display: flex;
  align-items: center;
  justify-content: center;
}
.kutu {
  background: #fff;
  border-radius: 8px;
  padding: 24px;
  max-width: 460px;
  width: 100%;
}
.kutu h3 { margin-top: 0; }
.kutu-aciklama { color: var(--soluk); font-size: 14px; }
.kutu label { display: block; font-size: 13px; color: var(--soluk); margin-bottom: 4px; }
.kutu .onay { display: flex; gap: 8px; align-items: flex-start; margin-top: 12px; color: var(--metin); }
.kutu-dugmeler { display: flex; gap: 8px; justify-content: flex-end; margin-top: 16px; }
