}
.etiket.genis { color: #fff; background: var(--yikici); border-color: var(--yikici); }

.rozet { display: inline-block; min-width: 22px; text-align: center; }
.rozet.uyari { color: #fff; background: var(--uyari); border-radius: 10px; padding: 0 6px; }

.durum-rozet { font-size: 12px; padding: 2px 6px; border-radius: 3px; background: #f0f0f0; }
.durum-askida { background: #ffe9d6; color: var(--uyari); }
.durum-yasakli { background: #ffdedb; color: var(--yikici); }
.durum-dondurulmus { background: #e8e8f5; color: #444; }

.ozet { display: grid; grid-template-columns: 180px 1fr; gap: 4px 16px; }
.ozet dt { color: var(--soluk); }
.ozet dd { margin: 0; }

/* Hassas erisimin her zaman gorunur olmasi bilincli: moderator neye
   baktigini ve bunun kaydedildigini unutmamali. */
.uyari-serit {
  background: #fff4ea;
  border-left: 3px solid var(--vurgu);
