.kutu label { display: block; font-size: 13px; color: var(--soluk); margin-bottom: 4px; }
.kutu .onay { display: flex; gap: 8px; align-items: flex-start; margin-top: 12px; color: var(--metin); }
.kutu-dugmeler { display: flex; gap: 8px; justify-content: flex-end; margin-top: 16px; }
