/* SLOOIN MODERASYON PANELI - tasarim sistemi (2026-09-18 yeniden tasarim).
   Uygulamayla ayni jeton ailesi: beyaz zemin, tek turuncu vurgu
   (#FE7813), Instrument Sans; basliklarda Bricolage Grotesque yalnizca
   kabuk ve sayfa basliklarinda. Panel bir vitrin degil: olcut okunurluk,
   yanlis tiklamanin zor olmasi ve her hassas eylemin gorunur olmasi. */

@import url('https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:wght@600;700&family=Instrument+Sans:wght@400;500;600;700&display=swap');

:root {
  --zemin: #F6F4F1;
  --yuzey: #FFFFFF;
  --metin: #17130F;
  --ikincil: #6E6660;
  --soluk: #A39B93;
  --cizgi: #E6E0D8;
  --cizgiKoyu: #D5CDC3;
  --turuncu: #FE7813;
  --turuncuBasili: #E06509;
  --turuncuZemin: #FFF3E8;
  --turuncuYazi: #D95F05;
  --yesil: #1F8A4C;
  --yesilZemin: #E8F5EC;
  --kirmizi: #C0261A;
  --kirmiziZemin: #FBE9E7;
  --sari: #8A5A00;
  --sariZemin: #FFF4D6;
  --mavi: #1F5FA8;
  --maviZemin: #E8F0FA;
  --golge: 0 1px 2px rgba(23, 19, 15, .05), 0 8px 24px rgba(23, 19, 15, .06);
  --yuvarlak: 12px;
  --yuvarlakKucuk: 8px;
  --kenar: 220px;
}
@media (prefers-color-scheme: dark) {
  :root {
    --zemin: #121110; --yuzey: #1C1A17; --metin: #F3EEE8; --ikincil: #B0A79E; --soluk: #7A736C;
    --cizgi: #2E2A26; --cizgiKoyu: #3A3530; --turuncuZemin: #3A2412; --turuncuYazi: #FF9A4D;
    --yesilZemin: #15301F; --kirmiziZemin: #3A1512; --sariZemin: #332A10; --sari: #E5B85C;
    --maviZemin: #14243A; --mavi: #7FB0F0; --golge: none;
  }
}

* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  font-family: "Instrument Sans", system-ui, -apple-system, "Segoe UI", sans-serif;
  color: var(--metin);
  background: var(--zemin);
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}
a { color: var(--turuncuYazi); text-decoration: none; }
a:hover { text-decoration: underline; }
h1, h2, h3 { margin: 0; font-family: "Bricolage Grotesque", "Instrument Sans", sans-serif; letter-spacing: -.01em; }
h1 { font-size: 26px; }
h2 { font-size: 22px; }
h3 { font-size: 16px; }
code { font-family: ui-monospace, Menlo, Consolas, monospace; font-size: .92em; background: var(--zemin); padding: 1px 5px; border-radius: 5px; }
:focus-visible { outline: 2px solid var(--turuncu); outline-offset: 2px; }

/* ---------- KABUK: kenar cubugu + icerik ---------- */
.kabuk { display: grid; grid-template-columns: var(--kenar) 1fr; min-height: 100%; }
.kenar {
  position: sticky; top: 0; height: 100vh;
  background: var(--yuzey); border-right: 1px solid var(--cizgi);
  padding: 18px 14px; display: flex; flex-direction: column; gap: 4px;
}
.marka { display: flex; align-items: center; gap: 9px; padding: 4px 8px 16px; font-family: "Bricolage Grotesque", sans-serif; font-weight: 700; font-size: 17px; color: var(--turuncu); }
.marka-isaret { width: 26px; height: 26px; border-radius: 8px; background: var(--turuncu); color: #fff; display: inline-flex; align-items: center; justify-content: center; font-size: 15px; }
.kenar nav { display: flex; flex-direction: column; gap: 4px; }
.kenar nav a {
  display: flex; align-items: center; justify-content: space-between; gap: 8px;
  padding: 9px 10px; border-radius: 10px; color: var(--metin); font-weight: 500; font-size: 14px;
}
.kenar nav a:hover { background: var(--zemin); text-decoration: none; }
.kenar nav a.aktif { background: var(--turuncuZemin); color: var(--turuncuYazi); font-weight: 600; }
.sayi-rozeti { font-size: 11px; font-weight: 700; background: var(--turuncu); color: #fff; border-radius: 999px; padding: 1px 7px; min-width: 20px; text-align: center; line-height: 16px; }
.moderator { margin-top: auto; border-top: 1px solid var(--cizgi); padding-top: 12px; font-size: 13px; display: grid; gap: 6px; }
.moderator b { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.aal { display: inline-flex; align-items: center; gap: 6px; color: var(--yesil); font-size: 12px; font-weight: 600; }
.aal::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--yesil); }
.icerik { padding: 24px 28px 48px; max-width: 1180px; width: 100%; }

@media (max-width: 820px) {
  .kabuk { grid-template-columns: 1fr; }
  .kenar { position: static; height: auto; flex-direction: row; align-items: center; flex-wrap: wrap; gap: 6px; padding: 10px 12px; border-right: 0; border-bottom: 1px solid var(--cizgi); }
  .marka { padding: 4px 8px; }
  .kenar nav { flex-direction: row; flex-wrap: wrap; flex: 1; }
  .kenar nav a { padding: 7px 10px; font-size: 13px; }
  .moderator { margin-top: 0; border-top: 0; padding-top: 0; }
  .moderator b { display: none; }
  .icerik { padding: 16px; }
}

/* ---------- SAYFA BASLIGI ---------- */
.sayfa-ust { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 18px; flex-wrap: wrap; }
.sayfa-ust h2 { display: flex; align-items: center; gap: 10px; }
.sayfa-ust .alt { color: var(--ikincil); font-size: 13px; margin-top: 2px; }
.geri { display: inline-flex; align-items: center; gap: 6px; color: var(--ikincil); font-size: 13px; margin-bottom: 10px; }
.geri:hover { color: var(--turuncuYazi); text-decoration: none; }

/* ---------- KARTLAR ---------- */
.kartlar { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 12px; margin-bottom: 22px; }
.kart { background: var(--yuzey); border: 1px solid var(--cizgi); border-radius: var(--yuvarlak); padding: 14px 16px; }
.kart.tikla { cursor: pointer; transition: border-color .15s; }
.kart.tikla:hover { border-color: var(--cizgiKoyu); }
.kart-etiket { font-size: 12px; color: var(--ikincil); font-weight: 600; letter-spacing: .04em; text-transform: uppercase; }
.kart-sayi { font-family: "Bricolage Grotesque", sans-serif; font-size: 28px; font-weight: 700; margin-top: 4px; font-variant-numeric: tabular-nums; }
.kart-sayi.vurgu { color: var(--turuncuYazi); }
.kart-not { font-size: 12px; color: var(--soluk); margin-top: 2px; }

.blok { background: var(--yuzey); border: 1px solid var(--cizgi); border-radius: var(--yuvarlak); padding: 16px 18px; margin-bottom: 14px; }
.blok > h3, .blok-baslik { font-family: "Instrument Sans", sans-serif; font-size: 12px; color: var(--ikincil); font-weight: 600; letter-spacing: .04em; text-transform: uppercase; margin: 0 0 10px; display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.blok.tehlike { border-color: #F2C9C4; background: var(--kirmiziZemin); }
.blok.tehlike > h3 { color: var(--kirmizi); }
.blok.bilgi { background: var(--turuncuZemin); border-color: transparent; }
.yapiskan { position: sticky; top: 16px; }

.iki-sutun { display: grid; grid-template-columns: minmax(0, 1fr) 340px; gap: 18px; align-items: start; }
@media (max-width: 960px) { .iki-sutun { grid-template-columns: 1fr; } .yapiskan { position: static; } }

/* ---------- OZET SATIRLARI (dl) ---------- */
.ozet { display: grid; grid-template-columns: 150px 1fr; gap: 6px 16px; margin: 0; }
.ozet dt { color: var(--ikincil); font-size: 13px; }
.ozet dd { margin: 0; overflow-wrap: anywhere; }
.icerik-kutu { background: var(--zemin); border-radius: 10px; padding: 12px 14px; font-size: 14px; white-space: pre-wrap; overflow-wrap: anywhere; }
.icerik-kutu .zaman { display: block; margin-top: 6px; }
.zaman { font-size: 12px; color: var(--soluk); font-variant-numeric: tabular-nums; }
.k { color: var(--ikincil); font-size: 13px; }

/* ---------- CIPLER (filtre) ---------- */
.cipler { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 12px; align-items: center; }
.cip { border: 1px solid var(--cizgi); background: var(--yuzey); border-radius: 999px; padding: 5px 12px; font: inherit; font-size: 13px; color: var(--ikincil); cursor: pointer; }
.cip:hover { border-color: var(--cizgiKoyu); color: var(--metin); }
.cip.aktif { background: var(--metin); color: var(--yuzey); border-color: var(--metin); }
.cip .adet { opacity: .7; margin-left: 4px; }
.cipler .ayrac { flex: 1; }

/* ---------- TABLO ---------- */
.tablo-kap { background: var(--yuzey); border: 1px solid var(--cizgi); border-radius: var(--yuvarlak); overflow-x: auto; }
table { width: 100%; border-collapse: collapse; font-size: 14px; }
th { text-align: left; font-size: 12px; color: var(--ikincil); font-weight: 600; letter-spacing: .03em; text-transform: uppercase; padding: 10px 12px; border-bottom: 1px solid var(--cizgi); white-space: nowrap; }
td { padding: 11px 12px; border-bottom: 1px solid var(--cizgi); vertical-align: middle; font-variant-numeric: tabular-nums; }
tbody tr:last-child td { border-bottom: 0; }
tbody tr.satir-link { cursor: pointer; }
tbody tr.satir-link:hover td { background: var(--zemin); }
tr.gizlenmis td { color: var(--soluk); }
tr.okuma td { background: var(--turuncuZemin); }
td .ikincil, .ikincil { color: var(--ikincil); }
.sag { text-align: right; }

/* ---------- ROZETLER ---------- */
.rozet { display: inline-flex; align-items: center; gap: 6px; border-radius: 999px; padding: 3px 10px; font-size: 12px; font-weight: 600; white-space: nowrap; }
.rozet::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: currentColor; flex: none; }
.rozet.turuncu { background: var(--turuncuZemin); color: var(--turuncuYazi); }
.rozet.sari { background: var(--sariZemin); color: var(--sari); }
.rozet.yesil { background: var(--yesilZemin); color: var(--yesil); }
.rozet.gri { background: var(--zemin); color: var(--ikincil); }
.rozet.kirmizi { background: var(--kirmiziZemin); color: var(--kirmizi); }
.rozet.mavi { background: var(--maviZemin); color: var(--mavi); }
.rozet.noktasiz::before { display: none; }
.sayac { display: inline-block; min-width: 26px; text-align: center; border-radius: 999px; padding: 1px 8px; font-size: 12px; font-weight: 600; background: var(--zemin); color: var(--ikincil); }
.sayac.uyari { background: var(--turuncuZemin); color: var(--turuncuYazi); }

.hedef { display: inline-flex; align-items: center; gap: 8px; }
.hedef-ikon { width: 26px; height: 26px; border-radius: 8px; background: var(--zemin); display: inline-flex; align-items: center; justify-content: center; font-size: 13px; flex: none; }
.hedef-ad { font-weight: 500; }
.hedef-tur { color: var(--soluk); font-size: 12px; }

/* ---------- DUGMELER ---------- */
button, .dugme {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  padding: 9px 14px; border-radius: 10px; font: inherit; font-weight: 600; font-size: 14px;
  border: 1px solid var(--cizgi); background: var(--yuzey); color: var(--metin); cursor: pointer;
  text-decoration: none; line-height: 1.2;
}
button:hover, .dugme:hover { border-color: var(--cizgiKoyu); text-decoration: none; }
button:disabled { opacity: .5; cursor: default; border-color: var(--cizgi); }
.birincil { background: var(--turuncu); border-color: var(--turuncu); color: #fff; }
.birincil:hover:not(:disabled) { background: var(--turuncuBasili); border-color: var(--turuncuBasili); }
.yikici { color: var(--kirmizi); border-color: #E7B8B2; }
.yikici:hover:not(:disabled) { background: var(--kirmiziZemin); border-color: var(--kirmizi); }
.hayalet { border-color: transparent; background: transparent; color: var(--ikincil); }
.hayalet:hover { background: var(--zemin); border-color: transparent; color: var(--metin); }
.kucuk { padding: 6px 10px; font-size: 13px; border-radius: 8px; }
.genis { width: 100%; }
.satir { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }

/* ---------- FORM ---------- */
label.alan { display: block; font-size: 12px; color: var(--ikincil); font-weight: 600; margin: 10px 0 4px; }
label.alan:first-child { margin-top: 0; }
input, select, textarea {
  width: 100%; padding: 9px 12px; border: 1px solid var(--cizgi); border-radius: 10px;
  font: inherit; font-size: 14px; background: var(--yuzey); color: var(--metin);
}
input:focus, select:focus, textarea:focus { outline: 2px solid var(--turuncu); outline-offset: 0; border-color: var(--turuncu); }
textarea { resize: vertical; min-height: 84px; }
select { appearance: none; background-image: linear-gradient(45deg, transparent 50%, var(--ikincil) 50%), linear-gradient(135deg, var(--ikincil) 50%, transparent 50%); background-position: calc(100% - 18px) 50%, calc(100% - 13px) 50%; background-size: 5px 5px; background-repeat: no-repeat; padding-right: 32px; }
.arama { display: flex; gap: 8px; }
.arama input { flex: 1; }
.dar { max-width: 200px; }
.onay-satiri { display: flex; gap: 10px; align-items: flex-start; margin-top: 12px; font-size: 14px; }
.onay-satiri input { width: auto; margin-top: 3px; }
fieldset { border: 1px solid var(--cizgi); border-radius: 10px; padding: 10px 14px; margin: 12px 0; display: grid; gap: 6px; }
legend { font-size: 12px; color: var(--ikincil); font-weight: 600; padding: 0 6px; }
fieldset label { display: flex; gap: 8px; align-items: center; font-size: 14px; }
fieldset input { width: auto; }
.ipucu { color: var(--ikincil); font-size: 12px; margin: 4px 0 0; }
.ipucu.hata { color: var(--kirmizi); }

/* ---------- DURUM METINLERI ---------- */
.durum { color: var(--ikincil); font-size: 14px; margin: 0; }
.durum.hata { color: var(--kirmizi); background: var(--kirmiziZemin); border-radius: 10px; padding: 10px 14px; display: flex; gap: 12px; align-items: center; justify-content: space-between; }
.durum.bilgi { color: var(--yesil); background: var(--yesilZemin); border-radius: 10px; padding: 10px 14px; }
.bos { background: var(--yuzey); border: 1px dashed var(--cizgiKoyu); border-radius: var(--yuvarlak); padding: 32px 20px; text-align: center; }
.bos b { display: block; color: var(--metin); font-size: 15px; margin-bottom: 4px; }
.iskelet { display: grid; gap: 8px; }
.iskelet span { display: block; height: 14px; border-radius: 6px; background: linear-gradient(90deg, var(--zemin) 25%, var(--cizgi) 50%, var(--zemin) 75%); background-size: 200% 100%; animation: parla 1.2s infinite; }
@keyframes parla { from { background-position: 200% 0; } to { background-position: -200% 0; } }
