          onayMetni="Bu kişinin bütün konuşmasını açtığımı ve bunun kaydedildiğini biliyorum."
          onIptal={() => setGenisKutuAcik(false)}
          onSonuc={(gerekce) => ac(gerekce, null)}
        />
      )}
    </section>
  )
}

