  const i = document.getElementById(inputId); if (!i) return 'yok:'+inputId;
  i.focus();
  const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set;
  setter.call(i, metin); i.dispatchEvent(new Event('input',{bubbles:true}));
  await new Promise(r=>setTimeout(r,800));
  const secenekler=[...document.querySelectorAll('[id*="option"]')].map(o=>o.innerText.trim());
  i.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',code:'Enter',keyCode:13,bubbles:true}));
  await new Promise(r=>setTimeout(r,600));
  return secenekler.slice(0,6).join(' ; ');
};
